import{_ as n,o as a,c as i,ai as t}from"./chunks/framework.BxxKhjs3.js";const e="/pub-blog/assets/0036e9ed-1420-44e7-9fdb-9c93ceeecac8.DyWsFLCE.gif",l="/pub-blog/assets/2.CcB4JQQz.gif",p="/pub-blog/assets/3.bmiapWYh.gif",r="/pub-blog/assets/image-20240815003658047.DQV0ApGN.png",h="/pub-blog/assets/4.nQeGSv0u.gif",d="/pub-blog/assets/image-20240815005522635.qa-n9tki.png",o="/pub-blog/assets/image-20240815005558987.7gvZMaNl.png",k="/pub-blog/assets/image-20240815005706165.Dyn_t0UU.png",c="/pub-blog/assets/image-20240815005751149.Cl-KLKye.png",E="/pub-blog/assets/5.wSzRUato.gif",g="/pub-blog/assets/qyvON.BIlEE7hE.png",b="/pub-blog/assets/6.C0JB5bro.gif",m="/pub-blog/assets/7.DxuWesAu.gif",u="/pub-blog/assets/8.BtTk45hS.gif",y="/pub-blog/assets/9.DHjVspCU.gif",B="/pub-blog/assets/10.C1EYInpB.gif",D=JSON.parse('{"title":"HarmonyOS Next 动画大全01-属性动画","description":"","frontmatter":{},"headers":[],"relativePath":"鸿蒙开发技巧/HarmonyOS Next 动画大全/HarmonyOS Next 动画大全01-属性动画/HarmonyOS Next 动画大全01-属性动画.md","filePath":"鸿蒙开发技巧/HarmonyOS Next 动画大全/HarmonyOS Next 动画大全01-属性动画/HarmonyOS Next 动画大全01-属性动画.md","lastUpdated":1730788610000,"__rawMarkdown":"# HarmonyOS Next 动画大全01-属性动画\\n\\n## 介绍\\n\\n动画，指的是我们应用中的元素，在发生位置、大小、颜色、形状等属性变化时，可以产出一个缓慢变化的效果。让用户的焦点一直跟随\\n\\n在应用的行动中，增加用户使用的体验和让用户知道当前的行动进度。\\n\\n如下图的就是有无动画的效果对比：(*图片来自华为鸿蒙应用开发文档*)\\n\\n\\n\\n![0000000000011111111.20240813092100.74430171962011375350726834762233:50001231000000:2800:7AB76D86444207B1B1944C345569A4BF364A1ACC4A7D63F7E09FFF25FB1D9333.gif](https://alliance-communityfile-drcn.dbankcdn.com/FileServer/getFile/cmtyPub/011/111/111/0000000000011111111.20240813092100.74430171962011375350726834762233:50001231000000:2800:7AB76D86444207B1B1944C345569A4BF364A1ACC4A7D63F7E09FFF25FB1D9333.gif?needInitFileName=true?needInitFileName=true)\\n\\n另外，我们在使用手机应用这么多年中，动画的效果比比皆是。\\n\\n**网易云音乐**\\n\\n![0036e9ed-1420-44e7-9fdb-9c93ceeecac8](readme.assets/0036e9ed-1420-44e7-9fdb-9c93ceeecac8.gif)\\n\\n**酷我音乐**\\n\\n![2](readme.assets/2.gif)\\n\\n**酷狗音乐**\\n\\n![3](readme.assets/3.gif)\\n\\n\\n\\n## 动画分类\\n\\n在 Harmony Next中，动画的分类主要有以下几种\\n\\n![image-20240815003658047](readme.assets/image-20240815003658047.png)\\n\\n那么我们今天主要讲解前面的两种： **属性动画**和**帧动画**。\\n\\n属性动画又分为 **属性动画 animation**  和 **显式动画 animateTo**， 帧动画就是 **@ohos.animator (动画)**\\n\\n**这篇文章只讲解属性动画 animation**。后续的其他动画会陆续发表。\\n\\n那为什么将他们归类到一起呢，因为他们核心思想都是利用常见的样式属性，指定开始状态和结束状态，从而实现动画效果。\\n\\n下面我们就直接开始吧。\\n\\n## 可以实现动画的属性\\n\\n首先我们需要理解具体那些样式属性可以出现动画效果。参考官网给出的定义：\\n\\n| 分类     | 说明                                           |\\n| -------- | ---------------------------------------------- |\\n| 布局属性 | 位置、大小、内边距、外边距、对齐方式、权重等。 |\\n| 仿射变换 | 平移、旋转、缩放、锚点等。                     |\\n| 背景     | 背景颜色、背景模糊等。                         |\\n| 内容     | 文字大小、文字颜色，图片对齐方式、模糊等。     |\\n| 前景     | 前景颜色等。                                   |\\n| Overlay  | Overlay属性等。                                |\\n| 外观     | 透明度、圆角、边框、阴影等。                   |\\n\\n以上的这些属性都可以简单总结为一个原则： 存在中间状态的属性可以有动画属性。那什么又是中间状态呢：\\n\\n比如人的高度发展是存在中间状态的 ： **小万的身高由100cm 长到 146cm**，那么中间的状态有 **101cm、102cm、。。146cm**等。\\n\\n所以上面表格中的 **宽度、坐标、边距、缩放、背景颜色(rgb(0,0,0) ->rgb(255,255,255)) 等就都存在中间状态**\\n\\n---\\n\\n同理 人的性别 或者 人的生死是不存在中间状态的：**小万男生变成女生？？？  小万生变到死？？？**\\n\\n所以**可见性-visibility、优先级-zIndex** 都是不存在中间状态的 因此就没有办法实现动画效果\\n\\n## 属性动画 animation\\n\\n属性动画 animation 是我们最简单实现动画的技术了。直接上效果\\n\\n![4](readme.assets/4.gif)\\n\\n\\n\\n\\n\\n**代码**\\n\\n```typescript\\n@Entry\\n@Component\\nstruct Index {\\n  // 缩放倍数\\n  @State\\n  scaleXY: number = 1\\n  // 背景颜色\\n  @State\\n  bgColor: string = \\"#0094ff\\"\\n\\n  build() {\\n    Column() {\\n      Button(\\"点我就生气\\")\\n        .scale({\\n          x: this.scaleXY,\\n          y: this.scaleXY\\n        })\\n        .backgroundColor(this.bgColor)\\n          // ️️ ❤️❤️❤️ 属性动画 \\n        .animation({})\\n        .onClick(() => {\\n          // 点击修改属性\\n          this.scaleXY = 2\\n          this.bgColor = \\"#f00\\"\\n        })\\n    }\\n    .width(\\"100%\\")\\n    .padding(30)\\n  }\\n}\\n```\\n\\n**代码解释**\\n\\n1. 设置样式 初始属性\\n\\n   ![image-20240815005522635](readme.assets/image-20240815005522635.png)\\n\\n2. 给按钮元素添加上样式属性\\n\\n   ![image-20240815005558987](readme.assets/image-20240815005558987.png)\\n\\n3. 给按钮设置属性动画 `animation`\\n\\n   ![image-20240815005706165](readme.assets/image-20240815005706165.png)\\n\\n4. 点击按钮时，修改属性，动画自动生效\\n\\n   ![image-20240815005751149](readme.assets/image-20240815005751149.png)\\n\\n   \\n\\n   \\n\\n   \\n\\n   \\n\\n   最后需要注意的是：在animation**之上**的样式属性会有动画效果，在animation**之下**的样式属性不会有动画效果\\n\\n   ```jsx\\n     Button(\\"点我就生气\\")\\n       // 在animation之上的样式属性会有动画效果\\n       .scale({\\n         x: this.scaleXY,\\n         y: this.scaleXY\\n       })\\n       .animation({})// \\n       // 在animation之下的样式属性不会有动画效果\\n       .backgroundColor(this.bgColor)\\n   ```\\n\\n   ![5](readme.assets/5.gif)\\n\\n## 属性动画 animation 参数\\n\\n属性动画接收传入配置参数实现调整动画的执行过程。如动画执行时间、次数等等。\\n\\n```\\nanimation(配置参数)\\n```\\n\\n| 名称       | 描述                                            | 示例            |\\n| ---------- | ----------------------------------------------- | --------------- |\\n| duration   | 动画执行时间，单位毫秒                          | 1000            |\\n| tempo      | 动画执行速度，默认是1，最小是0                  | 1               |\\n| curve      | 动画曲线 比如匀速、先快后慢等                   | Curve.linear    |\\n| delay      | 延迟时间 单位毫秒                               | 1000            |\\n| iterations | 动画执行次数，-1 为无限                         | 1               |\\n| playMode   | 动画播放模式 如播放两次时，每次都是从头开始播放 | PlayMode.Normal |\\n| onFinish   | 动画结束的回调函数                              |                 |\\n\\n### duration\\n\\n动画执行时间比较好理解，根据你传入的时间来决定整个动画多长时间执行完\\n\\n```\\n.animation({\\n  // 500毫秒执行完毕\\n  duration: 500,\\n})\\n```\\n\\n### tempo\\n\\n执行速度、默认是1。最小值是0。如果\\n\\n1. duration为1 ，tempo为1，那么动画1s执行完毕\\n2. duration为1 ，tempo为0.1，那么动画10s执行完毕\\n\\n### curve\\n\\n动画曲线，在动画执行时间一定的情况下，执行动画的速度可以快可慢，举个不恰当的例子：\\n\\n假设小万要在公司花1分钟走到厕所：\\n\\n1. 小万可以匀速的走完\\n2. 小万一开始不着急，**慢慢走**，中途突然来状况了，后半段路就要**走快一点**    先慢后快\\n3. 小万一开始很着急，**跑着去**，中途忍不住了，也干脆放弃了，后半段路就走慢一点  先快后慢\\n\\n\\n\\n可选值参考：\\n\\n| 名称                | 描述                                                         |\\n| :------------------ | :----------------------------------------------------------- |\\n| **Linear**          | 表示动画从头到尾的速度都是相同的。                           |\\n| Ease                | 表示动画以低速开始，然后加快，在结束前变慢，CubicBezier(0.25, 0.1, 0.25, 1.0)。 |\\n| EaseIn              | 表示动画以低速开始，CubicBezier(0.42, 0.0, 1.0, 1.0)。       |\\n| EaseOut             | 表示动画以低速结束，CubicBezier(0.0, 0.0, 0.58, 1.0)。       |\\n| EaseInOut           | 表示动画以低速开始和结束，CubicBezier(0.42, 0.0, 0.58, 1.0)。 |\\n| FastOutSlowIn       | 标准曲线，CubicBezier(0.4, 0.0, 0.2, 1.0)。                  |\\n| LinearOutSlowIn     | 减速曲线，CubicBezier(0.0, 0.0, 0.2, 1.0)。                  |\\n| FastOutLinearIn     | 加速曲线，CubicBezier(0.4, 0.0, 1.0, 1.0)。                  |\\n| ExtremeDeceleration | 急缓曲线，CubicBezier(0.0, 0.0, 0.0, 1.0)。                  |\\n| Sharp               | 锐利曲线，CubicBezier(0.33, 0.0, 0.67, 1.0)。                |\\n| Rhythm              | 节奏曲线，CubicBezier(0.7, 0.0, 0.2, 1.0)。                  |\\n| Smooth              | 平滑曲线，CubicBezier(0.4, 0.0, 0.4, 1.0)。                  |\\n| Friction            | 阻尼曲线，CubicBezier(0.2, 0.0, 0.2, 1.0)。                  |\\n\\n再配上一张图参考\\n\\n![img](readme.assets/qyvON.png)\\n\\n### delay\\n\\n延迟时间，默认为0，当你设置了之后，执行动画时会先延迟，然后再开始执行\\n\\n### iterations\\n\\n动画执行次数，默认为1次，-1为无限\\n\\n### playMode\\n\\n动画播放模式，提供4个选项\\n\\n| 名称             | 描述                                                         |\\n| :--------------- | :----------------------------------------------------------- |\\n| Normal           | 动画正向播放。                                               |\\n| Reverse          | 动画反向播放。                                               |\\n| Alternate        | 动画在奇数次（1、3、5...）正向播放，在偶数次（2、4、6...）反向播放。 |\\n| AlternateReverse | 动画在奇数次（1、3、5...）反向播放，在偶数次（2、4、6...）正向播放。 |\\n\\n理解为类似开车一样，从出发地A 然后开到终点B 如果 一次路途看成是执行一次动画的话，那么执行4次动画时：\\n\\n1. **Normal**    \\n   1. A-B\\n   2. A-B\\n   3. A-B\\n   4. A-B\\n2. **Reverse**\\n   1. B-A\\n   2. B-A\\n   3. B-A\\n   4. B-A\\n3. **Alternate**\\n   1. A-B\\n   2. B-A\\n   3. A-B\\n   4. B-A\\n4. **AlternateReverse**\\n   1. B-A\\n   2. A-B\\n   3. B-A\\n   4. A-B\\n\\n#### 初始代码\\n\\n```typescript\\n@Entry\\n@Component\\nstruct Index {\\n  @State\\n  translateX: number = 0\\n\\n  build() {\\n    Column() {\\n      Button(\\"点我就移动\\")\\n        .translate({ x: this.translateX })\\n        .animation({\\n          iterations: 4,\\n          playMode: PlayMode.Normal\\n        })\\n        .onClick(() => {\\n          this.translateX = 240\\n        })\\n    }\\n    .width(\\"100%\\")\\n    .padding({\\n      top: 30\\n    })\\n    .alignItems(HorizontalAlign.Start)\\n  }\\n}\\n```\\n\\n#### Normal\\n\\n```typescript\\n.animation({\\n  iterations: 4,\\n  playMode: PlayMode.Normal\\n})\\n```\\n\\n1. A-B\\n2. A-B\\n3. A-B\\n4. A-B\\n\\n![6](readme.assets/6.gif)\\n\\n\\n\\n#### Reverse\\n\\n```typescript\\n.animation({\\n  iterations: 4,\\n  playMode: PlayMode.Reverse\\n})\\n```\\n\\n1. B-A\\n2. B-A\\n3. B-A\\n4. B-A\\n\\n![7](readme.assets/7.gif)\\n\\n\\n\\n#### Alternate\\n\\n```typescript\\n.animation({\\n  iterations: 4,\\n  playMode: PlayMode.Alternate\\n})\\n```\\n\\n1. A-B\\n2. B-A\\n3. A-B\\n4. B-A\\n\\n![8](readme.assets/8.gif)\\n\\n#### AlternateReverse\\n\\n1. B-A\\n2. A-B\\n3. B-A\\n4. A-B\\n\\n![9](readme.assets/9.gif)\\n\\n\\n\\n```typescript\\n.animation({\\n  iterations: 4,\\n  playMode: PlayMode.AlternateReverse\\n})\\n```\\n\\n### onFinish\\n\\n动画执行完成后回调函数\\n\\n```\\n.animation({\\n  onFinish() {\\n    AlertDialog.show({ message: \\"奥运落幕啦\\" })\\n  }\\n})\\n```\\n\\n![10](readme.assets/10.gif)\\n\\n\\n\\n## 总结\\n\\n\\n\\n动画能够提升用户体验并使应用程序更加生动有趣。通过使用动画，开发者可以平滑地展示UI元素的变化，例如位置、大小、颜色或形状的变化。本文档将重点介绍Harmony Next中的属性动画，并提供一些基本概念和示例代码。\\n\\n### 可以实现动画的属性\\n\\n可以实现动画效果的属性包括但不限于：\\n- 布局属性（位置、大小等）\\n- 仿射变换（平移、旋转等）\\n- 背景（颜色、模糊等）\\n- 内容（文字大小、颜色等）\\n- 前景（颜色等）\\n- Overlay属性\\n- 外观（透明度、圆角等）\\n\\n这些属性之所以能实现动画，是因为它们存在中间状态。\\n\\n### 属性动画 `animation`\\n\\n属性动画是最简单的动画实现方式之一。它通过改变UI元素的属性值来实现动画效果。\\n\\n### 注意事项\\n\\n- 在`animation`之上的样式属性会有动画效果。\\n- 在`animation`之下的样式属性不会有动画效果。\\n\\n### 属性动画 `animation` 参数\\n\\n属性动画可以通过不同的参数来调整动画的执行过程，包括：\\n- `duration`（动画持续时间）\\n- `tempo`（动画速度）\\n- `curve`（动画曲线）\\n- `delay`（延迟时间）\\n- `iterations`（动画重复次数）\\n- `playMode`（动画播放模式）\\n- `onFinish`（动画完成后的回调）\\n\\n每个参数都有具体的含义和用途，可以根据需要灵活调整动画效果。\\n\\n"}'),F={name:"鸿蒙开发技巧/HarmonyOS Next 动画大全/HarmonyOS Next 动画大全01-属性动画/HarmonyOS Next 动画大全01-属性动画.md"};function C(A,s,v,x,f,_){return a(),i("div",null,[...s[0]||(s[0]=[t("",100)])])}const N=n(F,[["render",C]]);export{D as __pageData,N as default};
